# Generates ../fixtures_test.mbt: reference float transforms computed with
# Little CMS 2.19 (the version vendored by lcms2-sys 4.0.7, built as a shared
# library and loaded through LCMS_LIB) for the ICC profiles in this directory.
#   python3 -I mkprofiles.py .   # synthetic profiles
#   LCMS_LIB=/path/liblcms2.so python3 -I gen_fixtures.py
import base64, os, random, struct, sys, itertools
HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import lcmsref
names = ['srgb_v4_rel', 'srgb_linear_v4_rel', 'gray_linear_v4', 'gray_srgb_v4', 'brg_v2_curv',
         'rgb_v4_lutab', 'cmyk_v2_lut', 'rgb_v2_lut_lab', 'rgb_v4_mixed_trc', 'gray_v4_para',
         'gray_v2_gamma', 'mch5_v4', 'two_v4', 'gray_v4_clut']
data = {n: open(os.path.join(HERE, n + '.icc'), 'rb').read() for n in names}
pairs = [
    ('cmyk_v2_lut', 'srgb_linear_v4_rel'), ('cmyk_v2_lut', 'srgb_v4_rel'), ('srgb_v4_rel', 'cmyk_v2_lut'),
    ('rgb_v4_lutab', 'srgb_v4_rel'), ('srgb_linear_v4_rel', 'rgb_v4_lutab'),
    ('rgb_v2_lut_lab', 'srgb_v4_rel'), ('srgb_v4_rel', 'rgb_v2_lut_lab'),
    ('rgb_v4_mixed_trc', 'srgb_linear_v4_rel'), ('srgb_v4_rel', 'rgb_v4_mixed_trc'),
    ('brg_v2_curv', 'srgb_v4_rel'), ('srgb_v4_rel', 'brg_v2_curv'),
    ('gray_v4_para', 'srgb_v4_rel'), ('srgb_v4_rel', 'gray_v2_gamma'), ('gray_linear_v4', 'gray_srgb_v4'),
    ('gray_v2_gamma', 'gray_linear_v4'), ('mch5_v4', 'srgb_v4_rel'), ('two_v4', 'srgb_v4_rel'),
    ('gray_v4_clut', 'srgb_linear_v4_rel'), ('cmyk_v2_lut', 'rgb_v4_lutab'), ('rgb_v2_lut_lab', 'cmyk_v2_lut'),
]
def bits(f): return struct.unpack('<I', struct.pack('<f', f))[0]
out = ['// Generated by testdata/gen_fixtures.py from Little CMS 2.19 float transforms. Do not edit.', '']
for n in names:
    out += ['///|', 'let icc_%s : String =' % n]
    b64 = base64.b64encode(data[n]).decode()
    for i in range(0, len(b64), 96):
        out.append('  #|' + b64[i:i + 96])
    out.append('')
out += ['///|', 'fn fixture_profile(name : String) -> Bytes {', '  match name {']
for n in names:
    out.append('    "%s" => b64decode(icc_%s)' % (n, n))
out += ['    _ => abort("unknown profile")', '  }', '}', '']
out += ['///|', '/// (src, dst, intent, input bits, expected output bits)',
        'let fixture_cases : Array[(String, String, Int, Array[UInt], Array[UInt])] = [']
rnd = random.Random(7)
for (s, d) in pairs:
    for intent in range(4):
        nin = lcmsref.lc.cmsChannelsOf(lcmsref.lc.cmsGetColorSpace(lcmsref.profile(data[s])))
        pts = [tuple(rnd.random() for _ in range(nin)) for _ in range(6)]
        pts += [tuple([0.0] * nin), tuple([1.0] * nin), tuple([0.5] * nin), tuple([1.05] * nin), tuple([-0.02] * nin)]
        _, nout, ref = lcmsref.transform(data[s], data[d], intent, pts)
        inb = ', '.join('0x%08X' % bits(v) for p in pts for v in p)
        outb = ', '.join('0x%08X' % bits(v) for r in ref for v in r)
        out.append('  ("%s", "%s", %d, [%s], [%s]),' % (s, d, intent, inb, outb))
out += [']', '']
open(os.path.join(HERE, '..', 'fixtures_test.mbt'), 'w').write('\n'.join(out))
print('cases', len(pairs) * 4)
